  .rate{font-size:11px;color:#aaa;margin-top:5px}
  .stars{font-size:15px;color:#d7d7d7;letter-spacing:-2px;margin-top:-2px}
  .right{width:240px;flex:none}
  .right h3{font-size:14px;font-weight:normal;margin:8px 0 14px}
  .right .social{position:absolute}
  .feature-title{font-family:Georgia,serif;font-size:13px;color:#287d6d;font-weight:bold;line-height:1.2;margin-bottom:8px}
  .feature-img{width:230px;height:130px;object-fit:cover;display:block;margin-bottom:8px}
  .likes{font-size:11px;color:#888;margin-bottom:25px}
  .lists-title{font-size:14px;margin-bottom:9px}
  .list-row{display:flex;align-items:center;border-bottom:1px solid #eee;padding:5px 0;color:#388476;font-size:12px;line-height:1.1}
  .list-row span{width:145px}
  .mini-covers{display:flex;gap:3px}
  .mini-covers img{width:25px;height:34px;object-fit:cover}
  .more{font-size:12px;color:#388476;margin:14px 0 27px}
  .author-title{font-size:15px;margin-bottom:12px}
  .author-copy{font-size:12px;line-height:1.35;margin-bottom:13px}
  .small-button{font-size:11px;padding:5px 10px;border:1px solid #ccc;background:#f7f7f5;border-radius:2px;margin-right:6px}
  @media(max-width:1100px){
    .nav-inner,.hero-inner,.content{width:950px}
    .main{width:650px}.right{display:none}.hero-copy{margin-left:300px}
    .badge{left:70px}
  }
</style>
