<script>
const base="__PLACEHOLDER_ASSETS_BASE_DIR__/";
const datasets={
  2024:[
    ["Fiction","102.jpg"],["Historical Fiction","106.jpg"],["Mystery & Thriller","001.jpg"],["Romance","004.jpg"],
    ["Romantasy","007.jpg"],["Fantasy","010.jpg"],["Science Fiction","013.jpg"],["Horror","016.jpg"]
  ],
  2022:[
    ["Fiction","099.jpg"],["Mystery & Thriller","104.jpg"],["Historical Fiction","107.jpg"],["Fantasy","002.jpg"],
    ["Romance","005.jpg"],["Science Fiction","008.jpg"],["Horror","011.jpg"],["Humor","014.jpg"]
  ]
};
const settings={
  2024:{title:"Readers’ Favorite Books of 2024",sub:"Announcing readers' favorite books of 2024! Congratulations to the winners<br>of the 16th annual Goodreads Choice Awards.",votes:"6,261,936 Votes Cast",opening:"Nov. 12 -<br>24",final:"Nov. 26 -<br>Dec. 1",winner:"Dec. 5"},
  2022:{title:"READERS' FAVORITE BOOKS OF<br>2022",sub:"Announcing the winners of the Annual Goodreads Choice Awards.",votes:"Votes Cast:<br>5,779,854",opening:"Nov. 15 -<br>27",final:"Nov. 29 -<br>Dec. 4",winner:"Dec. 8"}
};
function render(year){
  const data=datasets[year]||datasets[2024], s=settings[year]||settings[2024];
  const hero=document.getElementById("hero");
  hero.className="hero "+(year===2022?"awards2022":"awards2024");
  document.getElementById("badgeYear").textContent=year;
  document.getElementById("heroTitle").innerHTML=s.title;
  document.getElementById("heroSubtitle").innerHTML=s.sub;
  document.getElementById("votes").innerHTML=s.votes;
  document.getElementById("opening").innerHTML=s.opening;
  document.getElementById("final").innerHTML=s.final;
  document.getElementById("winner").innerHTML=s.winner;
  document.getElementById("yearsHeading").textContent=year===2022?"Other Years":"Previous Years";
  document.querySelectorAll(".years a").forEach(a=>{
    a.classList.toggle("active",a.dataset.year==year);
  });
  document.getElementById("bookGrid").innerHTML=data.map(item=>`
    <article class="card">
      <h3>${item[0]}</h3>
      <img class="cover" src="${base}${item[1]}" width="150" height="235" alt="${item[0]} book">
      <button class="want btn">Want to Read</button>
      <div class="rate">Rate this book</div>
      <div class="stars">★★★★★</div>
    </article>`).join("");
}
document.querySelectorAll(".years a").forEach(a=>{
  a.addEventListener("click",e=>{
    e.preventDefault();
    const y=Number(a.dataset.year);
    if(y===2024||y===2022) render(y);
  });
});
render(2024);
</script>
</body>
